"use client";

import { usePointerParallax } from "../hooks/usePointerParallax";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/**
 * A field of soft pastel blobs, stars, and clouds that drift toward the
 * pointer — `pointer-parallax`. Each shape is inline SVG (no images),
 * positioned absolutely and given a `--depth` (0.04–0.18); styles.css
 * multiplies the normalized pointer offset by depth so nearer shapes
 * follow more and far ones barely. The whole field also bobs gently on
 * mutually-prime idle periods, so it is alive even without a pointer
 * (touch devices, reduced-but-present motion fallback).
 *
 * Decorative only: `aria-hidden`, pointer-transparent.
 */
export default function FloatingShapes() {
  const reduced = usePrefersReducedMotion();
  const ref = usePointerParallax<HTMLDivElement>(reduced);

  return (
    <div className="bounce-field" ref={ref} aria-hidden="true">
      {/* far layer — barely drifts */}
      <div className="bounce-field__layer bounce-field__layer--far">
        <Cloud className="bounce-shape bounce-shape--cloud1" />
        <Cloud className="bounce-shape bounce-shape--cloud2" />
        <Star className="bounce-shape bounce-shape--star1" tone="butter" />
      </div>

      {/* mid layer */}
      <div className="bounce-field__layer bounce-field__layer--mid">
        <Blob className="bounce-shape bounce-shape--blob1" tone="peach" />
        <Blob className="bounce-shape bounce-shape--blob2" tone="sky" />
        <Star className="bounce-shape bounce-shape--star2" tone="peach" />
        <Blob className="bounce-shape bounce-shape--blob3" tone="grape" />
      </div>

      {/* near layer — drifts most */}
      <div className="bounce-field__layer bounce-field__layer--near">
        <Star className="bounce-shape bounce-shape--star3" tone="grape" />
        <Blob className="bounce-shape bounce-shape--blob4" tone="butter" />
        <Dot className="bounce-shape bounce-shape--dot1" tone="plum" />
        <Dot className="bounce-shape bounce-shape--dot2" tone="accent" />
      </div>
    </div>
  );
}

type Tone = "butter" | "sky" | "peach" | "grape" | "plum" | "accent";

function Blob({ className, tone }: { className: string; tone: Tone }) {
  return (
    <svg
      className={className}
      viewBox="0 0 120 120"
      width="120"
      height="120"
      focusable="false"
    >
      <path
        d="M60 8c14 0 22 10 28 22 4 8 24 10 24 30s-18 22-22 32-12 20-30 20-26-10-32-22S4 80 4 60 18 36 26 28 46 8 60 8z"
        fill={`var(--bounce-${tone})`}
      />
    </svg>
  );
}

function Star({ className, tone }: { className: string; tone: Tone }) {
  // a chunky 5-point star, rounded via stroke-linejoin
  const pts: string[] = [];
  const spikes = 5;
  const outer = 52;
  const inner = 24;
  for (let i = 0; i < spikes * 2; i += 1) {
    const r = i % 2 === 0 ? outer : inner;
    const a = (Math.PI * i) / spikes - Math.PI / 2;
    pts.push(`${(60 + Math.cos(a) * r).toFixed(1)},${(60 + Math.sin(a) * r).toFixed(1)}`);
  }
  return (
    <svg
      className={className}
      viewBox="0 0 120 120"
      width="96"
      height="96"
      focusable="false"
    >
      <polygon
        points={pts.join(" ")}
        fill={`var(--bounce-${tone})`}
        stroke="var(--bounce-ink)"
        strokeWidth="3"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function Cloud({ className }: { className: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 160 80"
      width="160"
      height="80"
      focusable="false"
    >
      <path
        d="M40 64c-14 0-26-8-26-22s12-22 26-22c3-9 12-16 24-16s22 7 26 18c3-1 6-2 10-2 14 0 26 10 26 24s-12 22-26 22H40z"
        fill="var(--bounce-cloud)"
        stroke="var(--bounce-ink)"
        strokeWidth="3"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function Dot({ className, tone }: { className: string; tone: Tone }) {
  return (
    <svg
      className={className}
      viewBox="0 0 40 40"
      width="40"
      height="40"
      focusable="false"
    >
      <circle cx="20" cy="20" r="16" fill={`var(--bounce-${tone})`} />
    </svg>
  );
}

"use client";

import { useSpringPress } from "../hooks/useSpring";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

type Book = {
  id: string;
  ko: string;
  en: string;
  age: string;
  tone: "sky" | "peach" | "grape" | "butter";
  blurbKo: string;
  blurbEn: string;
  /** one-word emoji-free emoji stand-in drawn as SVG */
  shape: "bunny" | "rocket" | "cloud" | "apple";
};

const BOOKS: Book[] = [
  {
    id: "bunny",
    ko: "토끼가 통통",
    en: "Bunny Boings",
    age: "만 2–4세",
    tone: "peach",
    blurbKo: "깡총거리는 토끼 한 마리. 어디로 튀어 갈까요?",
    blurbEn: "A rabbit who can't stop hopping. Where does she go?",
    shape: "bunny",
  },
  {
    id: "rocket",
    ko: "둥둥 로켓",
    en: "The Boing Rocket",
    age: "만 4–6세",
    tone: "sky",
    blurbKo: "찌릿, 슝, 통통. 작은 로켓의 첫 우주 여행.",
    blurbEn: "Spark, whoosh, boing. A tiny rocket's first trip to space.",
    shape: "rocket",
  },
  {
    id: "cloud",
    ko: "구름이 말랑말랑",
    en: "Squishy Cloud",
    age: "만 3–5세",
    tone: "grape",
    blurbKo: "구름을 만져보세요. 말랑. 한 번 더 만져보세요.",
    blurbEn: "Touch the cloud. Squish. Now poke it again.",
    shape: "cloud",
  },
  {
    id: "apple",
    ko: "사과가 콩콩",
    en: "The Bouncy Apple",
    age: "만 2–4세",
    tone: "butter",
    blurbKo: "굴러가는 사과 하나. 동글동글, 콩콩콩.",
    blurbEn: "One rolling apple. Round and round, boing boing boing.",
    shape: "apple",
  },
];

function CardShape({ shape }: { shape: Book["shape"] }) {
  if (shape === "bunny") {
    return (
      <svg viewBox="0 0 80 80" width="72" height="72" focusable="false" aria-hidden="true">
        <ellipse cx="40" cy="56" rx="22" ry="18" fill="var(--bounce-ink)" />
        <ellipse cx="30" cy="24" rx="6" ry="16" fill="var(--bounce-ink)" />
        <ellipse cx="50" cy="24" rx="6" ry="16" fill="var(--bounce-ink)" />
        <ellipse cx="30" cy="26" rx="3" ry="10" fill="var(--bounce-accent)" />
        <ellipse cx="50" cy="26" rx="3" ry="10" fill="var(--bounce-accent)" />
        <circle cx="33" cy="52" r="2.6" fill="var(--bounce-cream)" />
        <circle cx="47" cy="52" r="2.6" fill="var(--bounce-cream)" />
        <path d="M37 60 q3 3 6 0" stroke="var(--bounce-cream)" strokeWidth="2.4" fill="none" strokeLinecap="round" />
      </svg>
    );
  }
  if (shape === "rocket") {
    return (
      <svg viewBox="0 0 80 80" width="72" height="72" focusable="false" aria-hidden="true">
        <path d="M40 8c12 8 16 22 16 36H24c0-14 4-28 16-36z" fill="var(--bounce-plum)" />
        <circle cx="40" cy="30" r="6" fill="var(--bounce-cream)" />
        <path d="M24 44l-10 14 14-6z" fill="var(--bounce-accent)" />
        <path d="M56 44l10 14-14-6z" fill="var(--bounce-accent)" />
        <path d="M32 44c0 6 4 12 8 18 4-6 8-12 8-18z" fill="var(--bounce-accent)" />
      </svg>
    );
  }
  if (shape === "cloud") {
    return (
      <svg viewBox="0 0 80 80" width="72" height="72" focusable="false" aria-hidden="true">
        <path
          d="M24 56c-9 0-16-5-16-13s7-13 16-13c2-5 7-9 14-9s13 4 15 10c2-1 4-1 6-1 9 0 16 6 16 14s-7 12-16 12H24z"
          fill="var(--bounce-cream)"
          stroke="var(--bounce-ink)"
          strokeWidth="3"
          strokeLinejoin="round"
        />
      </svg>
    );
  }
  // apple
  return (
    <svg viewBox="0 0 80 80" width="72" height="72" focusable="false" aria-hidden="true">
      <path d="M40 26c4-8 14-10 20-6 0 12-8 18-20 18z" fill="var(--bounce-plum)" />
      <path
        d="M40 30c-14 0-24 10-24 24 0 12 10 20 24 20s24-8 24-20c0-14-10-24-24-24z"
        fill="var(--bounce-accent)"
        stroke="var(--bounce-ink)"
        strokeWidth="3"
      />
      <path d="M40 28c0-6 2-10 6-12" stroke="var(--bounce-plum)" strokeWidth="3" fill="none" strokeLinecap="round" />
    </svg>
  );
}

function Card({ book }: { book: Book }) {
  const reduced = usePrefersReducedMotion();
  const ref = useSpringPress<HTMLLIElement>(reduced);

  return (
    <li
      ref={ref}
      className={`bounce-book bounce-book--${book.tone}`}
      data-bounce-card
      tabIndex={0}
    >
      <div className="bounce-book__art" aria-hidden="true">
        <CardShape shape={book.shape} />
      </div>
      <p className="bounce-book__age">
        <span lang="ko">{book.age}</span>
      </p>
      <h3 className="bounce-book__title">
        <span lang="ko" className="bounce-book__ko">
          {book.ko}
        </span>
        <span className="bounce-book__en">{book.en}</span>
      </h3>
      <p className="bounce-book__blurb">
        <span lang="ko">{book.blurbKo}</span>
        <span className="bounce-book__blurb-en">{book.blurbEn}</span>
      </p>
    </li>
  );
}

/**
 * The shelf — four picture-book cards that bounce in with overshoot as the
 * section scrolls into view (`char-split-reveal`'s sibling card preset in
 * useBounceReveal), and each card squashes when you press it. The card is
 * a real list item (`<li>`) inside a `<ul>`; focusable so keyboard and
 * touch reach it; the spring press is the same rubber gesture as the hero
 * CTA.
 */
export default function SpringCards() {
  return (
    <section
      id="bounce-books"
      className="bounce-shelf"
      aria-labelledby="bounce-shelf-title"
    >
      <div className="bounce-sec">
        <span className="bounce-sec__no" aria-hidden="true">
          하나
        </span>
        <h2 className="bounce-sec__title" id="bounce-shelf-title">
          <span lang="ko">요즘 나오는 책</span>
          <span className="bounce-sec__title-en">on the shelf</span>
        </h2>
      </div>
      <p className="bounce-shelf__lede">
        <span lang="ko">네 권의 그림책 — 한 권씩 튀어 올라옵니다.</span>
        <span className="bounce-shelf__lede-en">
          Four picture books — each one bounces in to say hi.
        </span>
      </p>
      <ul className="bounce-shelf__grid">
        {BOOKS.map((b) => (
          <Card key={b.id} book={b} />
        ))}
      </ul>
    </section>
  );
}

// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/fredoka";
import "@fontsource/gaegu";

export const fredoka = { variable: "" };
export const gaegu = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-glyph spring config for the char-split reveal. */
const CHAR_STIFF = 320;
const CHAR_DAMP = 12;
const CHAR_MASS = 1;
const STAGGER_MS = 55;

/** Card pop spring config. */
const CARD_STIFF = 220;
const CARD_DAMP = 18;
const CARD_MASS = 1;
const CARD_STAGGER_MS = 90;

/** Resting & start values. */
const GLYPH_REST_Y = 0;
const GLYPH_START_Y = 34; // glyphs begin ~0.3em below their slot
const GLYPH_START_SC = 0.5;
const GLYPH_REST_SC = 1;

const CARD_REST_Y = 0;
const CARD_START_Y = 30;
const CARD_START_SC = 0.92;
const CARD_REST_SC = 1;

type Glyph = {
  el: HTMLElement;
  y: number;
  vy: number;
  sc: number;
  vsc: number;
  /** wall-clock ms at which the spring may start */
  startAt: number;
  triggered: boolean;
  started: boolean;
};

type Card = {
  el: HTMLElement;
  y: number;
  vy: number;
  sc: number;
  vsc: number;
  startAt: number;
  triggered: boolean;
  started: boolean;
};

/** One semi-implicit-Euler spring step on a scalar; returns [pos, vel, alive]. */
function spring1(
  pos: number,
  vel: number,
  goal: number,
  k: number,
  c: number,
  m: number,
  dt: number,
): [number, number, boolean] {
  const f = dt / 1000;
  const a = (-k * (pos - goal) - c * vel) / m;
  const nv = vel + a * f;
  const nx = pos + nv * f;
  const alive = Math.abs(nx - goal) > 0.0008 || Math.abs(nv) > 0.0008;
  return [nx, nv, alive];
}

/**
 * Bounces in two kinds of things as they enter the viewport:
 *
 * 1. `[data-bounce-text]` — a headline. The hook splits the text content
 *    into per-glyph `<span>`s (accessible: container keeps an aria-label,
 *    the animated spans are aria-hidden) and springs each glyph up from
 *    below with overshoot, staggered 55ms per glyph.
 * 2. `[data-bounce-card]` — a card. Springs translateY + scale with the
 *    softer card preset, batch-staggered 90ms within an observer batch.
 *
 * The pre-reveal state is gated behind the `.bounce-js` root class, so
 * without JavaScript everything is simply visible in its resting place.
 * Under reduced motion, everything resolves to its resting state on first
 * paint — no movement, no hidden content.
 *
 * Returns a ref to the root that contains the `[data-bounce-*]` targets.
 */
export function useBounceReveal<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const root = ref.current;
    if (!root) return;

    const textEls = Array.from(
      root.querySelectorAll<HTMLElement>("[data-bounce-text]"),
    );
    const cardEls = Array.from(
      root.querySelectorAll<HTMLElement>("[data-bounce-card]"),
    );

    // --- Reduced motion / no IO: split, but snap everything to rest. ----
    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of textEls) splitText(el);
      for (const el of cardEls) {
        el.style.transform = "";
        el.style.opacity = "1";
      }
      return;
    }

    // Split now; the .bounce-js pre-reveal CSS hides the glyphs only while
    // JS is alive, so SSR/first-paint keeps them visible at rest.
    for (const el of textEls) splitText(el);

    // Write each glyph's START position as an inline transform immediately,
    // so when it flips visible (opacity via [style]) it is already sitting
    // just below its slot, waiting for its stagger time.
    const glyphs: Glyph[] = [];
    for (const el of textEls) {
      const spans = el.querySelectorAll<HTMLElement>(".bounce-glyph");
      for (const span of Array.from(spans)) {
        const g: Glyph = {
          el: span,
          y: GLYPH_START_Y,
          vy: 0,
          sc: GLYPH_START_SC,
          vsc: 0,
          startAt: 0,
          triggered: false,
          started: false,
        };
        span.style.transform = `translateY(${GLYPH_START_Y}px) scale(${GLYPH_START_SC})`;
        glyphs.push(g);
      }
    }

    const cards: Card[] = cardEls.map((el) => {
      const c: Card = {
        el,
        y: CARD_START_Y,
        vy: 0,
        sc: CARD_START_SC,
        vsc: 0,
        startAt: 0,
        triggered: false,
        started: false,
      };
      el.style.transform = `translateY(${CARD_START_Y}px) scale(${CARD_START_SC})`;
      return c;
    });

    let raf = 0;
    let last = 0;

    const tick = (now: number) => {
      const dt = last ? Math.min(48, now - last) : 16.7;
      last = now;
      let alive = false;

      for (const g of glyphs) {
        if (!g.triggered) continue;
        if (!g.started) {
          if (now < g.startAt) {
            alive = true; // keep the loop alive until this glyph's cue
            continue;
          }
          g.started = true;
          // flip visible at the START position this frame, then spring up
          g.el.classList.add("bounce-glyph--in");
        }
        const [ny, nvy, ay] = spring1(g.y, g.vy, GLYPH_REST_Y, CHAR_STIFF, CHAR_DAMP, CHAR_MASS, dt);
        g.y = ny;
        g.vy = nvy;
        const [nsc, nvsc, as] = spring1(g.sc, g.vsc, GLYPH_REST_SC, CHAR_STIFF, CHAR_DAMP, CHAR_MASS, dt);
        g.sc = nsc;
        g.vsc = nvsc;
        g.el.style.transform = `translateY(${g.y.toFixed(2)}px) scale(${g.sc.toFixed(4)})`;
        if (ay || as) alive = true;
      }

      for (const c of cards) {
        if (!c.triggered) continue;
        if (!c.started) {
          if (now < c.startAt) {
            alive = true;
            continue;
          }
          c.started = true;
        }
        const [ny, nvy, ay] = spring1(c.y, c.vy, CARD_REST_Y, CARD_STIFF, CARD_DAMP, CARD_MASS, dt);
        c.y = ny;
        c.vy = nvy;
        const [nsc, nvsc, as] = spring1(c.sc, c.vsc, CARD_REST_SC, CARD_STIFF, CARD_DAMP, CARD_MASS, dt);
        c.sc = nsc;
        c.vsc = nvsc;
        c.el.style.transform = `translateY(${c.y.toFixed(2)}px) scale(${c.sc.toFixed(4)})`;
        if (ay || as) alive = true;
      }

      if (alive) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
        last = 0;
      }
    };

    const wake = () => {
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(tick);
      }
    };

    // One observer handles both, with a shared per-batch stagger counter
    // so cards arriving together fan out 90ms apart.
    let cardBatch = 0;
    const io = new IntersectionObserver(
      (hits) => {
        let localCard = 0;
        const now = performance.now();
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          if (el.hasAttribute("data-bounce-text")) {
            const spans = el.querySelectorAll<HTMLElement>(".bounce-glyph");
            spans.forEach((span, idx) => {
              const g = glyphs.find((gg) => gg.el === span);
              if (!g || g.triggered) return;
              g.triggered = true;
              g.startAt = now + idx * STAGGER_MS;
            });
            io.unobserve(el);
          } else {
            const c = cards.find((cc) => cc.el === el);
            if (!c || c.triggered) continue;
            c.triggered = true;
            c.startAt = now + (cardBatch + localCard) * CARD_STAGGER_MS;
            c.el.classList.add("is-in");
            localCard += 1;
            io.unobserve(el);
          }
        }
        cardBatch += localCard;
        wake();
      },
      { threshold: 0.15, rootMargin: "0px 0px -8% 0px" },
    );

    for (const el of textEls) io.observe(el);
    for (const el of cardEls) io.observe(el);

    return () => {
      io.disconnect();
      cancelAnimationFrame(raf);
    };
  }, [disabled]);

  return ref;
}

/**
 * Splits the text-node children of `el` into per-glyph `.bounce-glyph`
 * spans. Whitespace stays as plain text. The container must carry its own
 * `aria-label` (the full string); the spans are aria-hidden so the headline
 * is announced once, cleanly. Idempotent.
 */
function splitText(el: HTMLElement) {
  if (el.dataset.split === "1") return;
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  const targets: Text[] = [];
  let node = walker.nextNode();
  while (node) {
    targets.push(node as Text);
    node = walker.nextNode();
  }
  for (const text of targets) {
    const frag = document.createDocumentFragment();
    for (const ch of text.textContent ?? "") {
      if (ch === " " || ch === "\n" || ch === "\t") {
        frag.appendChild(document.createTextNode(ch));
        continue;
      }
      const span = document.createElement("span");
      span.className = "bounce-glyph";
      span.setAttribute("aria-hidden", "true");
      span.style.display = "inline-block";
      span.style.willChange = "transform";
      span.textContent = ch;
      frag.appendChild(span);
    }
    text.parentNode?.replaceChild(frag, text);
  }
  el.dataset.split = "1";
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const DRIFT_LERP = 0.06;

/**
 * Drives `--bounce-px` / `--bounce-py` (each −1…1) on the referenced element
 * — the floating background shapes' pointer drift. styles.css multiplies
 * these into small, capped, depth-scaled translations: nearer shapes drift
 * more, far ones barely. The lerp is gentle so the shapes feel like they
 * are catching up, not tracking.
 *
 * Fine pointers only — on touch the shapes simply bob on their idle loop
 * (the CSS idle animation carries the life instead), and under reduced
 * motion this hook does nothing; the CSS fallback for both variables is 0.
 *
 * The rAF loop pauses offscreen (IntersectionObserver) and when the tab is
 * hidden.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = DRIFT_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--bounce-px", x.toFixed(4));
      el.style.setProperty("--bounce-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--bounce-px");
      el.style.removeProperty("--bounce-py");
    };
  }, [disabled]);

  return ref;
}

