import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";

/** Spring presets, each tuned for a specific BOUNCE gesture. */
export type SpringPreset = "press" | "card" | "char";

type Config = { stiffness: number; damping: number; mass: number };

const CONFIGS: Record<SpringPreset, Config> = {
  // Buttons: fast squash on press, slightly underdamped so the release
  // overshoots ~6% and wobbles once before settling — the rubber snap.
  press: { stiffness: 380, damping: 14, mass: 1 },
  // Cards: a touch softer; the bounce-in settle after reveal.
  card: { stiffness: 220, damping: 18, mass: 1 },
  // Per-glyph headline reveal: snappier, more overshoot, lands loud.
  char: { stiffness: 320, damping: 12, mass: 1 },
};

type SpringState = {
  /** Two independent values so a press can squash (sx≠sy) and recover. */
  sx: number;
  sy: number;
  tx: number;
  ty: number;
  vx: number;
  vy: number;
  vangle: number;
  angle: number;
};

/** One body animated toward its target by one rAF step. */
function integrate(
  s: SpringState,
  target: Partial<SpringState>,
  cfg: Config,
  dt: number,
): boolean {
  const f = dt / 1000;
  let alive = false;

  const stepAxis = (
    pos: number,
    vel: number,
    goal: number,
  ): [number, number, boolean] => {
    const k = cfg.stiffness;
    const c = cfg.damping;
    const m = cfg.mass;
    // semi-implicit Euler: v += a*dt; x += v*dt
    const a = (-k * (pos - goal) - c * vel) / m;
    const nv = vel + a * f;
    const nx = pos + nv * f;
    const moving = Math.abs(nx - goal) > 0.0008 || Math.abs(nv) > 0.0008;
    return [nx, nv, moving];
  };

  if (target.sx !== undefined) {
    const [nx, nv, m] = stepAxis(s.sx, s.vx, target.sx);
    s.sx = nx;
    s.vx = nv;
    if (m) alive = true;
  }
  if (target.sy !== undefined) {
    const [nx, nv, m] = stepAxis(s.sy, s.vy, target.sy);
    s.sy = nx;
    s.vy = nv;
    if (m) alive = true;
  }
  if (target.ty !== undefined) {
    const [nx, nv, m] = stepAxis(s.ty, s.vangle, target.ty);
    s.ty = nx;
    s.vangle = nv;
    if (m) alive = true;
  }
  return alive;
}

/**
 * Attaches spring-press behaviour to a pressable element (button, link,
 * card). On pointer-down the element SQUASHES (wide and short); on release
 * a critically-underdamped spring snaps it back, overshooting slightly
 * (tall and thin) before it settles — the squash-and-stretch that says
 * "rubber".
 *
 * The spring writes only `transform` (scale + translate), never layout.
 * Under reduced motion the squash is replaced by a tiny static press-down
 * (no oscillation), and keyboard `:active` is covered by the CSS fallback.
 *
 * Returns a ref to attach to the element.
 */
export function useSpringPress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (disabled) return; // CSS handles a static press-down

    const cfg = CONFIGS.press;
    const s: SpringState = {
      sx: 1,
      sy: 1,
      tx: 0,
      ty: 0,
      vx: 0,
      vy: 0,
      vangle: 0,
      angle: 0,
    };
    let raf = 0;
    let last = 0;
    let pressing = false;
    let target: Partial<SpringState> = { sx: 1, sy: 1 };

    const write = () => {
      // translate is only used to nest a tiny press-down so the squash
      // looks like it pushes into the page; main motion is scale.
      el.style.transform = `translate3d(0, ${s.ty.toFixed(2)}px, 0) scale(${s.sx.toFixed(4)}, ${s.sy.toFixed(4)})`;
    };

    const tick = (now: number) => {
      const dt = last ? Math.min(48, now - last) : 16.7;
      last = now;
      const alive = integrate(s, target, cfg, dt);
      write();
      if (alive) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
        last = 0;
      }
    };

    const wake = () => {
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(tick);
      }
    };

    const onDown = (e: PointerEvent) => {
      if (e.pointerType === "keyboard") return;
      pressing = true;
      // Squash: wider and shorter, like a rubber stamp being pressed.
      target = { sx: 1.12, sy: 0.82, ty: 2 };
      s.vy = 0;
      wake();
    };
    const onUp = () => {
      if (!pressing) return;
      pressing = false;
      // Release: spring back through 1 with overshoot (the underdamped
      // spring naturally overshoots on the way to rest).
      target = { sx: 1, sy: 1, ty: 0 };
      wake();
    };

    el.addEventListener("pointerdown", onDown);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    el.addEventListener("blur", onUp);

    return () => {
      el.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
      el.removeEventListener("blur", onUp);
      cancelAnimationFrame(raf);
      el.style.transform = "";
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { fredoka, gaegu } from "./fonts";
import Hero from "./components/Hero";
import SpringCards from "./components/SpringCards";
import FloatingShapes from "./components/FloatingShapes";
import KidsFooter from "./components/KidsFooter";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useBounceReveal } from "./hooks/useBounceReveal";

/**
 * BOUNCE — 통통, a story studio for small humans.
 * A children's-book brand site where every UI element is made of rubber:
 * buttons squash-and-stretch on press, headline letters bounce in
 * one-by-one with overshoot, cards pop in on reveal, and soft pastel
 * shapes drift toward your pointer. Reactive springs — you don't drag
 * anything here, you just touch it and it bounces back.
 *
 * `.bounce-js` is added on mount so every pre-reveal style (glyphs hidden
 * before their bounce, cards waiting below) is JS-gated — with JavaScript
 * disabled, or under reduced motion, the full page simply sits in its
 * resting state: everything readable, nothing moving.
 */
export default function BouncePage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useBounceReveal<HTMLDivElement>(reduced);

  useEffect(() => {
    // Imperative on purpose: the class is a signal to CSS that JS is alive,
    // not React state — and it never changes once set.
    rootRef.current?.classList.add("bounce-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "bounce" }, "*");
  }, []);

  return (
    <div
      ref={rootRef}
      className={`${fredoka.variable} ${gaegu.variable} bounce-root`}
    >
      <FloatingShapes />

      <div ref={revealRef} className="bounce-stage">
        <Hero />
        <main>
          <SpringCards />
        </main>
        <KidsFooter />
      </div>
    </div>
  );
}

/* ==========================================================================
   BOUNCE — 통통, a story studio for small humans
   playful-pop · soft pastel · rounded everything · the page is rubber
   Scoped by convention to .bounce-root; classes prefixed bounce-.
   ========================================================================== */

.bounce-root {
  /* -- palette: pastels that carry dark text ---------------------------- */
  --bounce-butter: #fdf2c9;  /* page — the warm book page; ink 11.6:1 */
  --bounce-cream: #fff8e6;   /* lightest wash — hero sky, card fills; ink 12.3:1 */
  --bounce-sky: #bfe3ff;     /* card surface A; ink 9.7:1 */
  --bounce-peach: #ffd0b0;   /* card surface B; ink 9.2:1 */
  --bounce-grape: #d9c2ff;   /* card surface C; ink 8.1:1, plum large-only 3.6:1 */
  --bounce-cloud: #ffffff;   /* cloud fill */
  --bounce-ink: #3a2a4d;     /* primary text + outlines — 8.1–13.0:1 everywhere */
  --bounce-ink-soft: #5b4a6e;/* secondary text — 4.95:1 minimum (AA) */
  --bounce-plum: #7a4fb8;    /* accent text, links, wordmark fill — 4.10–5.77:1 */
  --bounce-accent: #ff8a5c;  /* CTA surface + spring blush — ink on it 5.6:1, never text */

  /* soft offset shadow stack — a rubber object resting on the page.
     No blur fog: two layered ink-alpha steps that read as a soft block. */
  --bounce-shadow-sm: 0 2px 0 rgba(58, 42, 77, 0.08), 0 6px 14px rgba(58, 42, 77, 0.12);
  --bounce-shadow-md: 0 3px 0 rgba(58, 42, 77, 0.10), 0 10px 22px rgba(58, 42, 77, 0.14);
  --bounce-shadow-lg: 0 4px 0 rgba(58, 42, 77, 0.12), 0 16px 32px rgba(58, 42, 77, 0.16);

  /* -- type: two round voices -------------------------------------------- */
  --bounce-font-display: "Fredoka", "Gaegu", "Fredoka", sans-serif;
  --bounce-font-ko: "Gaegu", "Apple SD Gothic Neo", sans-serif;
  --bounce-font-body: "Fredoka", "Gaegu", "Fredoka", sans-serif;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--bounce-butter);
  color: var(--bounce-ink);
  font-family: var(--bounce-font-body);
  font-size: clamp(15px, 0.5vw + 13px, 18px);
  line-height: 1.65;
  font-weight: 500;
  overflow-x: hidden;
  overflow-x: clip;
}

.bounce-root,
.bounce-root *,
.bounce-root *::before,
.bounce-root *::after {
  box-sizing: border-box;
}

.bounce-root h1,
.bounce-root h2,
.bounce-root h3,
.bounce-root p,
.bounce-root ul,
.bounce-root dl,
.bounce-root dd {
  margin: 0;
}

.bounce-root ul {
  padding: 0;
  list-style: none;
}

/* Korean is first-class: Gaegu, its own rhythm, words kept whole */
.bounce-root :lang(ko) {
  font-family: var(--bounce-font-ko);
  word-break: keep-all;
  line-height: 1.7;
  font-weight: 700;
}

/* Plum-on-butter selection, scoped to the entry root */
.bounce-root ::selection {
  background: var(--bounce-plum);
  color: var(--bounce-cream);
}

/* Keyboard focus: a plum ring with a soft halo — the same plum that
   outlines pressable things at rest. */
.bounce-root :focus-visible {
  outline: 3px solid var(--bounce-plum);
  outline-offset: 3px;
  border-radius: 12px;
}

.bounce-foot :focus-visible {
  outline-color: var(--bounce-cream);
}

/* Visually hidden, still spoken */
.bounce-vh {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ==========================================================================
   Floating shapes — pointer parallax + idle bob
   The field is decorative: aria-hidden, pointer-events none. Each layer
   multiplies --bounce-px/py (−1…1, set by usePointerParallax) by a depth
   factor so nearer shapes drift more. Idle bob is mutually-prime per
   shape so the field is never still when a pointer is absent.
   ========================================================================== */

.bounce-field {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.bounce-field__layer {
  position: absolute;
  inset: -8%;
}

.bounce-field__layer--far {
  transform: translate3d(
    calc(var(--bounce-px, 0) * 8px),
    calc(var(--bounce-py, 0) * 5px),
    0
  );
  opacity: 0.5;
}
.bounce-field__layer--mid {
  transform: translate3d(
    calc(var(--bounce-px, 0) * 18px),
    calc(var(--bounce-py, 0) * 12px),
    0
  );
  opacity: 0.75;
}
.bounce-field__layer--near {
  transform: translate3d(
    calc(var(--bounce-px, 0) * 30px),
    calc(var(--bounce-py, 0) * 20px),
    0
  );
  opacity: 0.9;
}

.bounce-shape {
  position: absolute;
  display: block;
  will-change: transform;
  /* idle bob — small, mutually-prime periods */
  animation: bounce-bob 6.4s ease-in-out infinite alternate;
}
.bounce-shape--cloud1 { top: 8%;  left: 4%;  animation-duration: 9.1s; }
.bounce-shape--cloud2 { top: 14%; right: 8%; animation-duration: 7.7s; }
.bounce-shape--star1 { top: 22%; left: 18%; animation-duration: 5.3s; }
.bounce-shape--blob1 { top: 6%;  right: 14%; animation-duration: 8.2s; }
.bounce-shape--blob2 { top: 30%; left: 6%;  animation-duration: 7.1s; }
.bounce-shape--star2 { top: 40%; right: 6%; animation-duration: 6.8s; }
.bounce-shape--blob3 { bottom: 18%; left: 12%; animation-duration: 9.8s; }
.bounce-shape--star3 { top: 52%; right: 16%; animation-duration: 5.9s; }
.bounce-shape--blob4 { bottom: 10%; right: 10%; animation-duration: 7.4s; }
.bounce-shape--dot1 { top: 60%; left: 22%; animation-duration: 4.6s; }
.bounce-shape--dot2 { bottom: 30%; left: 40%; animation-duration: 5.5s; }

@keyframes bounce-bob {
  from { translate: 0 -6px; }
  to   { translate: 0 6px; }
}

/* ==========================================================================
   Stage — sits above the floating field
   ========================================================================== */

.bounce-stage {
  position: relative;
  z-index: 1;
}

/* ==========================================================================
   Spring buttons — squash on press, overshoot on release.
   .bounce-btn--spring gets the JS spring via useSpringPress (writes inline
