.bounce-book--peach:hover { background: #ffdcc4; }
.bounce-book--grape { background: var(--bounce-grape); }
.bounce-book--grape:hover { background: #e2cfff; }
.bounce-book--butter { background: var(--bounce-butter); }
.bounce-book--butter:hover { background: #fef6d9; }

/* keyboard/reduced-motion press fallback (JS overrides on pointer) */
.bounce-js .bounce-book:active {
  transform: scale(1.06, 0.9);
}

.bounce-book__art {
  display: flex;
  align-items: center;
  justify-content: center;
  height: clamp(80px, 14vw, 110px);
  margin-bottom: 0.2rem;
}

.bounce-book__age {
  align-self: flex-start;
  font-family: var(--bounce-font-ko);
  font-weight: 700;
  font-size: 0.82rem;
  color: var(--bounce-ink);
  background: var(--bounce-cream);
  border: 2px solid var(--bounce-ink);
  border-radius: 999px;
  padding: 0.15em 0.7em;
}

.bounce-book__title {
  display: flex;
  flex-direction: column;
  gap: 0.1em;
  line-height: 1.05;
}
.bounce-book__ko {
  font-family: var(--bounce-font-ko);
  font-weight: 700;
  font-size: clamp(1.5rem, 3vw, 1.9rem);
  color: var(--bounce-ink);
}
.bounce-book__en {
  font-family: var(--bounce-font-display);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--bounce-ink-soft);
  letter-spacing: 0.01em;
}

.bounce-book__blurb {
  font-size: 0.95rem;
  color: var(--bounce-ink);
}
.bounce-book__blurb > span {
  display: block;
}
.bounce-book__blurb :lang(ko) {
  margin-bottom: 0.25rem;
}
.bounce-book__blurb-en {
  color: var(--bounce-ink-soft);
  font-size: 0.92em;
}

/* ==========================================================================
   Footer — the plum night-side
   ========================================================================== */

.bounce-foot {
  position: relative;
  margin-top: clamp(40px, 8vh, 90px);
  background: var(--bounce-plum);
  color: var(--bounce-cream);
  border-top: 3px solid var(--bounce-ink);
  padding: clamp(48px, 9vh, 96px) clamp(18px, 5vw, 56px) clamp(32px, 6vh, 56px);
  overflow: hidden;
}

.bounce-foot ::selection {
  background: var(--bounce-accent);
  color: var(--bounce-ink);
}

.bounce-foot__bye {
  font-family: var(--bounce-font-ko);
  font-weight: 700;
  font-size: clamp(2.6rem, 12vw, 7rem);
  line-height: 0.95;
  color: var(--bounce-cream);
  text-align: center;
  letter-spacing: -0.01em;
}
.bounce-foot__bye .bounce-glyph {
  /* keep glyphs visible inside the plum block at rest */
  color: var(--bounce-cream);
}

.bounce-foot__bye-en {
  text-align: center;
  font-family: var(--bounce-font-display);
  font-weight: 500;
  font-size: clamp(1rem, 2.4vw, 1.5rem);
  color: rgba(255, 248, 230, 0.8);
  letter-spacing: 0.08em;
  margin-top: 0.6rem;
  margin-bottom: clamp(2rem, 5vh, 3.2rem);
}

.bounce-foot__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(1.2rem, 3vw, 2.4rem);
  max-width: 1000px;
  margin-inline: auto;
}

.bounce-foot__cell {
  border-top: 2px solid rgba(255, 248, 230, 0.3);
  padding-top: 0.9em;
}

.bounce-foot__k {
  font-family: var(--bounce-font-ko);
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 0.04em;
  color: var(--bounce-butter);
  margin-bottom: 0.4em;
  display: flex;
  gap: 0.5em;
  align-items: baseline;
  flex-wrap: wrap;
}
.bounce-foot__k-en {
  font-family: var(--bounce-font-display);
  font-weight: 500;
  color: rgba(255, 248, 230, 0.7);
  font-size: 0.85em;
}

.bounce-foot__v {
  font-size: 0.95rem;
  line-height: 1.55;
}
.bounce-foot__v > span {
  display: block;
}
.bounce-foot__v :lang(ko) {
  margin-bottom: 0.2rem;
}
.bounce-foot__v-en {
  font-family: var(--bounce-font-display);
  font-weight: 400;
  color: rgba(255, 248, 230, 0.78);
}

.bounce-foot__legal {
  max-width: 1000px;
  margin: clamp(2rem, 5vh, 3.2rem) auto 0;
  text-align: center;
  font-size: 0.85rem;
  color: rgba(255, 248, 230, 0.7);
}

/* ==========================================================================
   Responsive composition
   ========================================================================== */

@media (max-width: 640px) {
  .bounce-hero__actions {
    flex-direction: column;
    align-items: stretch;
  }
  .bounce-btn {
    width: 100%;
  }
  .bounce-shelf__grid {
    grid-template-columns: 1fr;
  }
  .bounce-book__art {
    height: 90px;
  }
}

@media (max-width: 420px) {
  .bounce-sec__title {
    font-size: clamp(1.5rem, 8vw, 2rem);
  }
  .bounce-word--ko {
    font-size: clamp(2.8rem, 18vw, 5rem);
  }
  .bounce-word--en {
    font-size: clamp(2.5rem, 16vw, 4.5rem);
  }
}

/* ==========================================================================
   Reduced motion — the page sits still.
   Glyphs render at rest, cards rest in place, shapes stop drifting and
   bobbing, buttons keep a tiny static press-down only. Everything is fully
   readable; nothing is hidden.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .bounce-root .bounce-shape,
  .bounce-js .bounce-hero__hint {
    animation: none;
  }

  .bounce-field__layer--far,
  .bounce-field__layer--mid,
  .bounce-field__layer--near {
    transform: none;
  }

  /* glyphs visible at rest, cards visible at rest */
  .bounce-js [data-bounce-text] .bounce-glyph {
    opacity: 1;
    transform: none;
  }
  .bounce-js .bounce-book {
    opacity: 1;
    transform: none;
  }

  /* keep only a small static press-down; no oscillation */
  .bounce-btn,
  .bounce-btn--spring,
  .bounce-book {
    transition: transform 60ms linear;
  }
}
